import fs from 'fs'
import path from 'path'
import os from 'os'
import crypto from 'crypto'
import type { AudioOutput, SpeechOptions } from '../types'

export interface AudioCacheStats {
  entryCount: number
  totalBytes: number
  cacheDir: string
}

export interface AudioCacheManagerOptions {
  cacheDir?: string
  maxEntries?: number
  ttlMs?: number
}

interface CachedMetadata {
  key: string
  text: string
  sampleRateHz: number
  format: 'pcm16' | 'wav' | 'mp3' | 'ogg'
  durationMs?: number
  providerId?: string
  voice?: string
  createdAt: number
  fileSize: number
}

/**
 * AudioCacheManager
 *
 * Manages temporary session audio files generated by TTS providers.
 * - Computes deterministic SHA-256 keys from text, voice persona, provider, speed, and reference audio.
 * - Stores audio binary and metadata on disk in a session cache directory.
 * - Serves cached audio instantly (<5ms) for repeated prompts / sentences.
 * - Clears all temporary cache files on session end (app shutdown) and startup.
 */
export class AudioCacheManager {
  private cacheDir: string
  private maxEntries: number
  private ttlMs?: number

  constructor(options?: AudioCacheManagerOptions) {
    this.cacheDir =
      options?.cacheDir ||
      path.join(
        process.env.APPDATA || process.env.HOME || os.tmpdir(),
        'Jarvis',
        'cache',
        'audio-session'
      )
    this.maxEntries = options?.maxEntries || 200
    this.ttlMs = options?.ttlMs

    this.ensureCacheDir()
  }

  /**
   * Ensures the cache directory exists on disk.
   */
  public ensureCacheDir(): void {
    if (!fs.existsSync(this.cacheDir)) {
      try {
        fs.mkdirSync(this.cacheDir, { recursive: true })
      } catch (err) {
        console.warn('[AudioCacheManager] Failed to create cache directory:', err)
      }
    }
  }

  /**
   * Computes a deterministic SHA-256 cache key based on the speech parameters.
   */
  public computeKey(text: string, options?: SpeechOptions): string {
    const normalizedPayload = {
      text: (text || '').trim().toLowerCase(),
      voice: (options?.voice || 'default').toLowerCase(),
      providerId: (options?.providerId || 'auto').toLowerCase(),
      speed: Math.round(((options?.speed ?? 1.0) as number) * 100) / 100,
      speakerWav: (options?.speakerWav || '').toLowerCase()
    }

    return crypto.createHash('sha256').update(JSON.stringify(normalizedPayload)).digest('hex')
  }

  /**
   * Retrieves cached audio output for the given text and speech options.
   * Returns null if not cached, expired, or corrupted.
   */
  public async get(text: string, options?: SpeechOptions): Promise<AudioOutput | null> {
    const key = this.computeKey(text, options)
    const metaPath = path.join(this.cacheDir, `${key}.meta.json`)
    const binPath = path.join(this.cacheDir, `${key}.bin`)

    if (!fs.existsSync(metaPath) || !fs.existsSync(binPath)) {
      return null
    }

    try {
      const metaRaw = await fs.promises.readFile(metaPath, 'utf8')
      const meta: CachedMetadata = JSON.parse(metaRaw)

      // TTL expiration check if configured
      if (this.ttlMs && Date.now() - meta.createdAt > this.ttlMs) {
        this.deleteEntry(key)
        return null
      }

      const audioBuffer = await fs.promises.readFile(binPath)
      const data = new Uint8Array(audioBuffer)

      return {
        data,
        sampleRateHz: meta.sampleRateHz,
        format: meta.format,
        durationMs: meta.durationMs,
        providerId: meta.providerId,
        voice: meta.voice,
        cached: true
      }
    } catch (err) {
      console.warn(`[AudioCacheManager] Corrupted cache entry for key ${key}:`, err)
      this.deleteEntry(key)
      return null
    }
  }

  /**
   * Synchronous check if an entry exists in the cache.
   */
  public has(text: string, options?: SpeechOptions): boolean {
    const key = this.computeKey(text, options)
    const metaPath = path.join(this.cacheDir, `${key}.meta.json`)
    const binPath = path.join(this.cacheDir, `${key}.bin`)
    return fs.existsSync(metaPath) && fs.existsSync(binPath)
  }

  /**
   * Stores synthesized audio output and metadata into the session cache.
   */
  public async set(
    text: string,
    options: SpeechOptions | undefined,
    output: AudioOutput
  ): Promise<void> {
    if (!output || !output.data || output.data.length === 0) return

    try {
      await fs.promises.mkdir(this.cacheDir, { recursive: true })
      const key = this.computeKey(text, options)
      const metaPath = path.join(this.cacheDir, `${key}.meta.json`)
      const binPath = path.join(this.cacheDir, `${key}.bin`)

      // Manage capacity
      await this.enforceCapacityLimit()

      const meta: CachedMetadata = {
        key,
        text: (text || '').trim(),
        sampleRateHz: output.sampleRateHz,
        format: output.format,
        durationMs: output.durationMs,
        providerId: output.providerId || options?.providerId,
        voice: output.voice || options?.voice,
        createdAt: Date.now(),
        fileSize: output.data.length
      }

      await fs.promises.writeFile(binPath, Buffer.from(output.data))
      await fs.promises.writeFile(metaPath, JSON.stringify(meta, null, 2), 'utf8')
    } catch (err) {
      console.warn('[AudioCacheManager] Failed to cache audio entry:', err)
    }
  }

  /**
   * Clears all cached audio files and metadata.
   * Called on session startup and shutdown.
   */
  public clear(): { clearedCount: number; freedBytes: number } {
    if (!fs.existsSync(this.cacheDir)) {
      return { clearedCount: 0, freedBytes: 0 }
    }

    let clearedCount = 0
    let freedBytes = 0

    try {
      const files = fs.readdirSync(this.cacheDir)
      for (const file of files) {
        const filePath = path.join(this.cacheDir, file)
        try {
          const stats = fs.statSync(filePath)
          if (stats.isFile()) {
            freedBytes += stats.size
            fs.unlinkSync(filePath)
            clearedCount++
          }
        } catch {
          // ignore single file error
        }
      }
    } catch (err) {
      console.warn('[AudioCacheManager] Error while clearing cache:', err)
    }

    return { clearedCount, freedBytes }
  }

  /**
   * Retrieves current disk statistics for the audio cache.
   */
  public getStats(): AudioCacheStats {
    if (!fs.existsSync(this.cacheDir)) {
      return { entryCount: 0, totalBytes: 0, cacheDir: this.cacheDir }
    }

    let entryCount = 0
    let totalBytes = 0

    try {
      const files = fs.readdirSync(this.cacheDir)
      for (const file of files) {
        if (file.endsWith('.bin')) {
          entryCount++
        }
        const filePath = path.join(this.cacheDir, file)
        try {
          const stats = fs.statSync(filePath)
          if (stats.isFile()) {
            totalBytes += stats.size
          }
        } catch {
          // ignore
        }
      }
    } catch {
      // ignore
    }

    return {
      entryCount,
      totalBytes,
      cacheDir: this.cacheDir
    }
  }

  public getCacheDir(): string {
    return this.cacheDir
  }

  private deleteEntry(key: string): void {
    const metaPath = path.join(this.cacheDir, `${key}.meta.json`)
    const binPath = path.join(this.cacheDir, `${key}.bin`)
    try {
      if (fs.existsSync(metaPath)) fs.unlinkSync(metaPath)
      if (fs.existsSync(binPath)) fs.unlinkSync(binPath)
    } catch {
      // ignore
    }
  }

  private async enforceCapacityLimit(): Promise<void> {
    try {
      const files = await fs.promises.readdir(this.cacheDir)
      const binFiles = files.filter((f) => f.endsWith('.bin'))
      if (binFiles.length < this.maxEntries) return

      // Sort by modification time and delete oldest entries
      const fileStats = await Promise.all(
        binFiles.map(async (file) => {
          const full = path.join(this.cacheDir, file)
          const stat = await fs.promises.stat(full)
          return { file, mtime: stat.mtimeMs, key: file.replace('.bin', '') }
        })
      )

      fileStats.sort((a, b) => a.mtime - b.mtime)
      const excess = fileStats.slice(0, fileStats.length - this.maxEntries + 1)
      for (const item of excess) {
        this.deleteEntry(item.key)
      }
    } catch {
      // ignore
    }
  }
}
